using System.Diagnostics;using MiniCompiler.IR;using SemanticQueries.Core;using SemanticContracts;using Packages.BasicRange;using Baseline.DirectServices;
var i=new ValueId("i");var p=new ProgramPoint("p");var u=new CompilationUnit().Constant(i,5);var q=new RangeQuery();
static double Bench(Action a,int n=500_000){for(var i=0;i<10_000;i++)a();var sw=Stopwatch.StartNew();for(var i=0;i<n;i++)a();sw.Stop();return sw.Elapsed.TotalMilliseconds*1_000_000/n;}
var direct=new BasicRangeService(u);var registry=new RangeRegistry([direct]);var warm=new SemanticSession(new StaticPlan().Add(new BasicRangeProvider(u)),u.Revision,()=>u.Revision);_ = warm.Query(q,new(i,p));
Console.WriteLine("Toy benchmark — not a production compiler benchmark");Console.WriteLine($"direct typed: {Bench(()=>direct.TryGet(new(i,p),out _)):F1} ns/op");Console.WriteLine($"typed registry: {Bench(()=>registry.TryGet(new(i,p),out _)):F1} ns/op");Console.WriteLine($"semantic warm: {Bench(()=>warm.Query(q,new(i,p))):F1} ns/op");Console.WriteLine($"semantic cold: {Bench(()=>{var s=new SemanticSession(new StaticPlan().Add(new BasicRangeProvider(u)),u.Revision,()=>u.Revision);s.Query(q,new(i,p));},50_000):F1} ns/op");
